inline void Apply(Data&d){NalaEyeStageIdentity::Apply(d);if(d.vertices.size()!=NativeCount)return;d.vertices.reserve(NativeCount+std::size(Proxies));d.normals.reserve(NativeCount+std::size(Proxies));d.skin.reserve(NativeCount+std::size(Proxies));for(const auto&e:Proxies){d.vertices.push_back(Add(d.vertices[e.source],e.position));d.normals.push_back(Unit(Add(d.normals[e.source],e.normal)));d.skin.push_back(d.skin[e.source]);}}
inline const float* UV(){static const std::vector<float>uv=[](){const float*old=NalaEyeUV::ForBody();std::vector<float>v(old,old+2*std::size(NalaAppearance::SourceVertex));v.insert(v.end(),std::begin(ExtraUV),std::end(ExtraUV));return v;}();return uv.data();}
inline bool Render(const std::vector<V>&p,const std::vector<V>&n,std::vector<V>&out,std::vector<V>&normals){if(p.size()!=NativeCount+std::size(Proxies)||n.size()!=p.size())return false;out.resize(RenderCount);normals.resize(RenderCount);for(unsigned i=0;i<std::size(NalaAppearance::SourceVertex);++i){unsigned j=NalaAppearance::SourceVertex[i];out[i]=p[j];normals[i]=n[j];}for(const auto&e:Edits){V v{},nn{};for(unsigned k=0;k<3;++k){v=Add(v,Scale(p[e.source[k]],e.weight[k]));nn=Add(nn,Scale(n[e.source[k]],e.weight[k]));}out[e.render]=v;normals[e.render]=Unit(nn);}return true;}
inline bool Contact(const std::vector<V>&p,double scale,std::vector<double>&out){if(p.size()!=RenderCount||!(scale>0))return false;out.assign(RenderCount,0.);for(unsigned i:OcularVertices){double best=1e30;for(const auto&e:UpperEdges){V a=p[e[0]],d=Sub(p[e[1]],a),v=Sub(p[i],a);double length=Dot(d,d);if(length<1e-20)return false;double t=std::clamp(Dot(v,d)/length,0.,1.);V q=Sub(v,Scale(d,t));best=std::min(best,Dot(q,q));}double distance=std::sqrt(best)/scale;double t=std::clamp((distance-.0008)/.0052,0.,1.);out[i]=.48*(1-t*t*(3-2*t));}return true;}
inline unsigned Shade(unsigned colour,double contact){unsigned out=colour&0xff000000u;for(unsigned shift:{0u,8u,16u})out|=unsigned(std::lround(((colour>>shift)&255u)*(1.-contact)))<<shift;return out;}
